-- DCODE Low Balance: persistent hardware register, vendor directory and GST-aware quotations.
CREATE TABLE IF NOT EXISTS dcode_hardware_vendors (
 id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE,
 contact TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '',
 gstin TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '',
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS dcode_hardware_items (
 id TEXT PRIMARY KEY, description TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Other',
 model TEXT NOT NULL DEFAULT '', quantity NUMERIC(14,3) NOT NULL DEFAULT 1 CHECK(quantity>=0),
 unit TEXT NOT NULL DEFAULT 'nos', gst_rate NUMERIC(5,2) NOT NULL DEFAULT 18 CHECK(gst_rate>=0 AND gst_rate<=100),
 online_purchase BOOLEAN NOT NULL DEFAULT FALSE, purchase_url TEXT NOT NULL DEFAULT '',
 notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Draft',
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS dcode_hardware_quotes (
 id BIGSERIAL PRIMARY KEY, item_id TEXT NOT NULL REFERENCES dcode_hardware_items(id) ON DELETE CASCADE,
 vendor_id BIGINT NOT NULL REFERENCES dcode_hardware_vendors(id) ON DELETE CASCADE,
 unit_rate NUMERIC(14,2), gst_rate NUMERIC(5,2) NOT NULL DEFAULT 18 CHECK(gst_rate>=0 AND gst_rate<=100),
 source_type TEXT NOT NULL DEFAULT 'supplier' CHECK(source_type IN ('supplier','online')),
 product_url TEXT NOT NULL DEFAULT '', pack_size NUMERIC(14,3) NOT NULL DEFAULT 1 CHECK(pack_size>0),
 freight NUMERIC(14,2) NOT NULL DEFAULT 0, discount NUMERIC(14,2) NOT NULL DEFAULT 0,
 quotation_ref TEXT NOT NULL DEFAULT '', valid_until DATE, notes TEXT NOT NULL DEFAULT '',
 quoted_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 UNIQUE(item_id,vendor_id)
);
CREATE INDEX IF NOT EXISTS idx_dcode_hardware_quotes_item ON dcode_hardware_quotes(item_id);
CREATE TABLE IF NOT EXISTS dcode_hardware_register_state (
 id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(id), schema_version INTEGER NOT NULL DEFAULT 2,
 payload JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS dcode_hardware_register_revisions (
 id BIGSERIAL PRIMARY KEY, version_no INTEGER NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'Draft',
 note TEXT NOT NULL DEFAULT '', payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ON CONFLICT(id) DO UPDATE SET description=EXCLUDED.description, category=EXCLUDED.category, quantity=EXCLUDED.quantity, unit=EXCLUDED.unit, updated_at=now();
ON CONFLICT(item_id,vendor_id) DO UPDATE SET unit_rate=EXCLUDED.unit_rate, notes=EXCLUDED.notes, updated_at=now();
ON CONFLICT(item_id,vendor_id) DO UPDATE SET unit_rate=EXCLUDED.unit_rate, notes=EXCLUDED.notes, updated_at=now();
ON CONFLICT(item_id,vendor_id) DO UPDATE SET unit_rate=EXCLUDED.unit_rate, notes=EXCLUDED.notes, updated_at=now();
